-- Deiva Packaging schema v1. Import through phpMyAdmin on a NEW database.
-- Never run schema changes during an application build.
CREATE TABLE IF NOT EXISTS schema_versions (version INT PRIMARY KEY, applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS categories (slug VARCHAR(100) PRIMARY KEY, name VARCHAR(150) NOT NULL, description TEXT NOT NULL, image_url VARCHAR(1000) NOT NULL DEFAULT '', active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS products (id VARCHAR(100) PRIMARY KEY, slug VARCHAR(150) NOT NULL UNIQUE, name VARCHAR(200) NOT NULL, category VARCHAR(100) NOT NULL, material VARCHAR(100) NOT NULL, capacity VARCHAR(150) NOT NULL, dimensions VARCHAR(200) NOT NULL, colour VARCHAR(100) NOT NULL, description TEXT NOT NULL, image_url VARCHAR(1000) NOT NULL, compatible_ids JSON NOT NULL, active TINYINT NOT NULL DEFAULT 1, preview TINYINT NOT NULL DEFAULT 0, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(category,active), CONSTRAINT product_category_fk FOREIGN KEY(category) REFERENCES categories(slug)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS variants (id VARCHAR(100) PRIMARY KEY, product_id VARCHAR(100) NOT NULL, sku VARCHAR(100) NOT NULL UNIQUE, label VARCHAR(100) NOT NULL, units INT UNSIGNED NOT NULL, minimum INT UNSIGNED NOT NULL DEFAULT 1, increment INT UNSIGNED NOT NULL DEFAULT 1, price_cents BIGINT UNSIGNED NULL, stock INT UNSIGNED NULL, reserved INT UNSIGNED NOT NULL DEFAULT 0, active TINYINT NOT NULL DEFAULT 1, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT variant_product_fk FOREIGN KEY(product_id) REFERENCES products(id), CHECK(units>0), CHECK(minimum>0), CHECK(increment>0), CHECK(stock IS NULL OR stock>=reserved)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders (id VARCHAR(36) PRIMARY KEY, reference VARCHAR(40) NOT NULL UNIQUE, status_token_hash CHAR(64) NOT NULL UNIQUE, customer_name VARCHAR(100) NOT NULL, customer_email VARCHAR(200) NOT NULL, address_snapshot JSON NOT NULL, delivery_snapshot JSON NOT NULL, total_cents BIGINT UNSIGNED NOT NULL, gst_cents BIGINT UNSIGNED NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'aud', payment_status VARCHAR(30) NOT NULL DEFAULT 'pending', fulfilment_status VARCHAR(30) NOT NULL DEFAULT 'unfulfilled', notification_status VARCHAR(30) NOT NULL DEFAULT 'pending', checkout_session_id VARCHAR(150) NULL UNIQUE, inventory_deducted TINYINT NOT NULL DEFAULT 0, reservation_released TINYINT NOT NULL DEFAULT 0, expires_at DATETIME NOT NULL, notification_claimed_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(payment_status,expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS order_lines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id VARCHAR(36) NOT NULL, variant_id VARCHAR(100) NOT NULL, sku VARCHAR(100) NOT NULL, product_name VARCHAR(200) NOT NULL, label VARCHAR(100) NOT NULL, units INT UNSIGNED NOT NULL, quantity INT UNSIGNED NOT NULL, unit_price_cents BIGINT UNSIGNED NOT NULL, CONSTRAINT line_order_fk FOREIGN KEY(order_id) REFERENCES orders(id), CONSTRAINT line_variant_fk FOREIGN KEY(variant_id) REFERENCES variants(id), UNIQUE(order_id,variant_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payment_events (id VARCHAR(200) PRIMARY KEY, order_id VARCHAR(36) NOT NULL, event_type VARCHAR(100) NOT NULL, received_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT event_order_fk FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS enquiries (id VARCHAR(36) PRIMARY KEY, reference VARCHAR(40) NOT NULL UNIQUE, customer_name VARCHAR(100) NOT NULL, business_name VARCHAR(150) NOT NULL DEFAULT '', customer_email VARCHAR(200) NOT NULL, phone VARCHAR(40) NOT NULL DEFAULT '', postcode CHAR(4) NOT NULL, notes TEXT NOT NULL, lines_snapshot JSON NOT NULL, marketing_consent TINYINT NOT NULL DEFAULT 0, status VARCHAR(30) NOT NULL DEFAULT 'new', notification_status VARCHAR(30) NOT NULL DEFAULT 'pending', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS request_limits (limit_key CHAR(64) NOT NULL, bucket BIGINT NOT NULL, hits INT NOT NULL DEFAULT 1, PRIMARY KEY(limit_key,bucket)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO schema_versions(version) VALUES(1);
